LaunchedEffect(Unit) {
    var prev = 0L; var lag = 0.0; val dt = 1.0 / 60.0
    while (isActive) {                    // cancellation replaces the quit flag
        withFrameMillis { ms ->           // suspends until the next frame
            if (prev != 0L) {
                lag += (ms - prev) / 1000.0
                if (lag > 0.25) lag = 0.25
                while (lag >= dt) { step(dt); lag -= dt }   // fixed-step sim
                draw(lag / dt)
            }
            prev = ms
        }
    }
}

