val dt = 1.0 / 60
var next = TimeSource.Monotonic.markNow()
while (isActive) {
    step(dt)                                  // simulation advances by a fixed dt
    next += 16.milliseconds                   // deadline, not delay-from-now
    delay(next - TimeSource.Monotonic.markNow())   // at-least; cancellable
}
